var BSpline=function(t,n,i){this._points=t,this._linear=n,this._tension=i||0,this._deltaT=1/(this._points.length-1)};BSpline.prototype.getControlPointAtIndex=function(t){return t=Math.min(this._points.length-1,Math.max(t,0)),this._points[t]},BSpline.prototype.cardinalSplineAt=function(t,n,i,e,o,r){var s=r*r,h=s*r,l=(1-o)/2,a=l*(2*s-h-r),p=l*(-h+s)+(2*h-3*s+1),x=l*(h-2*s+r)+(-2*h+3*s),_=l*(h-s);return{x:t.x*a+n.x*p+i.x*x+e.x*_,y:t.y*a+n.y*p+i.y*x+e.y*_}},BSpline.prototype.calcAt=function(t){var n,i;1===t?(n=this._points.length-1,i=1):(n=parseInt(t/this._deltaT,10),i=(t-this._deltaT*n)/this._deltaT);var e=this.getControlPointAtIndex(n-1),o=this.getControlPointAtIndex(n+0),r=this.getControlPointAtIndex(n+1),s=this.getControlPointAtIndex(n+2);if(this._linear){var h=r.x-o.x,l=r.y-o.y;return{x:o.x+h*i,y:o.y+l*i}}return this.cardinalSplineAt(e,o,r,s,this._tension,i)};
